import { randomCode } from '../codes'
import type { CreateOptions, CreateResult } from '../match-object'
import type { LobbyPayload } from '../envelope'
import { handleCreateMatch, handleOpenMatch, type LaunchDeps } from './launch'

export * from './launch'

/** The RPC surface of a match object, as seen from the Worker. */
export interface MatchStub {
  create(opts: CreateOptions): Promise<CreateResult>
  lobby(): Promise<LobbyPayload | null>
  fetch(request: Request): Promise<Response>
}

export interface MatchEnv {
  MATCH: { getByName(name: string): MatchStub }
  LAUNCH_TOKEN: string
  CLIENT_ORIGIN: string
  APP_VERSION: string
  TEST_KNOBS?: string
}

export interface MatchFetchOptions {
  /** Refuse `bots > 0` unless TEST_KNOBS=1 (games whose bots exist only for local testing). */
  botsRequireTestKnobs?: boolean
}

const CODE_ROUTE = /^\/matches\/([A-Z0-9]{1,12})(\/ws)?$/

/** Every HTTP response is pinned to the one client origin. WebSocket upgrades bypass this (browsers apply no CORS to them). */
function cors(env: MatchEnv, res: Response): Response {
  const h = new Headers(res.headers)
  h.set('access-control-allow-origin', env.CLIENT_ORIGIN)
  h.set('access-control-allow-headers', 'authorization, content-type')
  h.set('access-control-allow-methods', 'GET, POST, OPTIONS')
  h.set('vary', 'origin')
  return new Response(res.body, { status: res.status, headers: h })
}

const json = (body: unknown, status = 200) => Response.json(body, { status, headers: { 'cache-control': 'no-store' } })

/** healthz, POST /matches (bearer), POST /matches/open, GET /matches/:code, GET /matches/:code/ws. */
export async function matchFetch(request: Request, env: MatchEnv, options: MatchFetchOptions = {}): Promise<Response> {
  const url = new URL(request.url)
  if (request.method === 'OPTIONS') return cors(env, new Response(null, { status: 204 }))
  if (url.pathname === '/healthz') return cors(env, json({ ok: true, version: env.APP_VERSION }))

  const creating = request.method === 'POST' && (url.pathname === '/matches' || url.pathname === '/matches/open')
  if (creating) {
    let body: unknown = null
    try {
      body = await request.json()
    } catch {
      return cors(env, json({ error: 'body must be JSON' }, 422))
    }
    const testing = env.TEST_KNOBS === '1'
    const deps: LaunchDeps = {
      createRoom: async (code, opts) => {
        if (options.botsRequireTestKnobs && opts.bots > 0 && !testing) return { status: 'invalid', message: 'this game has no bots' }
        return env.MATCH.getByName(code).create({ ...opts, clientOrigin: env.CLIENT_ORIGIN })
      },
      newCode: randomCode,
      clientOrigin: env.CLIENT_ORIGIN,
      launchToken: env.LAUNCH_TOKEN,
      now: Date.now,
    }
    const result =
      url.pathname === '/matches'
        ? await handleCreateMatch(request.headers.get('authorization') ?? undefined, body, deps)
        : await handleOpenMatch(body, deps)
    return cors(env, json(result.body, result.status))
  }

  const m = url.pathname.match(CODE_ROUTE)
  if (m && request.method === 'GET') {
    const stub = env.MATCH.getByName(m[1]!)
    if (m[2]) {
      // 404 before opening a socket when the room does not exist
      if ((await stub.lobby()) === null) return cors(env, new Response('no such match', { status: 404 }))
      return stub.fetch(request)
    }
    const lobby = await stub.lobby()
    return cors(env, lobby ? json(lobby) : new Response('no such match', { status: 404 }))
  }
  return cors(env, new Response('not found', { status: 404 }))
}
